INSERT INTO `tw_content` VALUES (15,'New listing: Carpet Game (TRG)','63c2c1bec95fe.jpg','<strong> \r\n<p>\r\n	<br />\r\nDear Poloniex users,<br />\r\n<br />\r\n<br />\r\n<br />\r\nWe are pleased to welcome The Rug Game (TRG) to Poloniex.<br />\r\n<br />\r\n<br />\r\n<br />\r\nPoloniex is about to launch The Rug Game (TRG), and the specific time is as follows.<br />\r\n<br />\r\nTRG recharge: January 16, 2023 at 14:45(UTC)<br />\r\nTRG/USDT transaction: January 16, 2023 at 16:00(UTC)<br />\r\n<br />\r\n<br />\r\nInterested in our list? Tell your friends and earn 4% from their transaction fees.<br />\r\n<br />\r\n<br />\r\n<br />\r\nProject information (this information is for reference only)<br />\r\n<br />\r\nToken Name: Carpet Game (TRG)<br />\r\n<br />\r\nTotal supply:<br />\r\n<br />\r\nTRG official website: https://theruggame.io/<br />\r\n<br />\r\nTRG token contract address: 0x93eeb426782bd88fcd4b48d7b0368cf061044928<br />\r\n<br />\r\n<br />\r\n<br />\r\nWhat is TRG? TRG is the core governance token of The Rug Game, which will exist outside the current 10-letter game and all future games.<br />\r\n<br />\r\n<br />\r\nYou know what you want us to list next? Please contact our listing team through listings@poloniex.com or let us know on Twitter!<br />\r\n<br />\r\n<br />\r\n<br />\r\nPoloniex team<br />\r\n<br />\r\nJanuary 16, 2023<br />\r\n<br />\r\n<br />\r\n<br />\r\nClick to download Poloniex App.<br />\r\n<br />\r\n<br />\r\n<br />\r\nFind us at-:<br />\r\n<br />\r\nTwitter: https ://twitter.com/Poloniex<br />\r\n<br />\r\nTelegraph: https ://t.me/PoloniexEnglish<br />\r\n<br />\r\nInstagram：https ://www.instagram.com/poloniexofficial/<br />\r\n<br />\r\nMedia: https ://medium.com/@Poloniex<br />\r\n<br />\r\nCustomer support Twitter: https://twitter.com/polosupport<br />\r\n<br />\r\nAnnouncement telegram: https://t.me/poloniex announcements<br />\r\n<br />\r\n<br />\r\n<br />\r\nRisk warning<br />\r\n<br />\r\nCryptographic currency investment faces high market risks. Please invest carefully. You are fully responsible for your investment decision, and Poloniex is not responsible for any losses you may suffer. Past performance is not a reliable predictor of future performance. You should only invest in products that you are familiar with and understand the risks. We are committed to providing users with safer, more efficient and more reliable digital asset trading services.<br />\r\n</p>\r\n<p>\r\n	<br />\r\n</p>\r\n</strong>','2022-03-16 17:47:50',2),(17,'九爷源码-www.bit-z8.com 更多源码前往本站','669e85e39376f.png','<h1 class=\"article-title\" style=\"font-size:32px;font-weight:normal;\">\r\n	<span style=\"font-size:12px;\">更多资源尽在九爷源码网-www.bit-z8.com</span>\r\n</h1>\r\n<a href=\"https://support.poloniex.com/hc/en-us/sections/360006455214-New-Coin-Listings\" class=\"article-sidebar-item\"></a>','2023-01-17 22:32:01',1);
